"use client"

import { Button } from "@/components/ui/button"
import { Spinner } from "@/components/ui/spinner"
import { cn } from "@/lib/utils"
import {
  CONFIGURED_ALERTS,
  SEVERITY_ORDER,
  type AlertAnalysis,
  type Detection,
} from "@/lib/mockups/behavioral-alerts-data"
import { ScenarioSettingsIcon } from "@/components/mockups/behavioral-alerts/icons"
import { formatTimeSeconds } from "@/components/mockups/behavioral-alerts/recording-player"
import { Seekable } from "@/components/mockups/behavioral-alerts/seekable"
import {
  SEVERITY_RULE,
  SeverityBadge,
} from "@/components/mockups/behavioral-alerts/severity"

/**
 * What the post-call analyst found, as the panel's own section.
 *
 * The three "nothing fired" cases are three different messages rather than one
 * blank panel — "no flag was detected", "no flag is configured" and "this
 * call was never analysed" are three different things to do next.
 */
export function AlertDetectionsBody({
  analysis,
  onConfigureAlerts,
  onSeek,
}: {
  analysis: AlertAnalysis
  /** Opens the scenario the alerts would be configured on. */
  onConfigureAlerts: () => void
  onSeek: (seconds: number) => void
}) {
  if (analysis.state === "pending") {
    return (
      <p className="flex items-center gap-2 text-sm text-muted-foreground">
        <Spinner className="size-4 shrink-0" />
        Analysing this call. Detections appear here when the post-call task
        finishes.
      </p>
    )
  }

  if (analysis.state === "unavailable") {
    return (
      <p className="text-sm text-muted-foreground">
        The call ended before anything was said, so there was no transcript to
        analyse.
      </p>
    )
  }

  if (analysis.state === "unconfigured") {
    return (
      <>
        <p className="text-sm text-muted-foreground">
          This scenario has no flags configured, so nothing was watched for.
        </p>
        <Button
          className="self-start"
          onClick={onConfigureAlerts}
          size="sm"
          variant="outline"
        >
          <ScenarioSettingsIcon />
          Configure flags
        </Button>
      </>
    )
  }

  if (analysis.detections.length === 0) {
    return (
      <p className="text-sm text-muted-foreground">
        No configured flag was detected on this call.
      </p>
    )
  }

  const detections = [...analysis.detections].sort(
    (a, b) =>
      SEVERITY_ORDER.indexOf(a.severity) - SEVERITY_ORDER.indexOf(b.severity),
  )

  return (
    <div className="flex flex-col gap-2">
      {detections.map((detection) => (
        <DetectionRow
          detection={detection}
          key={detection.id}
          onSeek={onSeek}
        />
      ))}
    </div>
  )
}

/** The label the collapsed section header carries, per state. */
export function detectionsSummary(analysis: AlertAnalysis) {
  if (analysis.state === "pending") return "Analysing"
  if (analysis.state === "unavailable") return "No transcript"
  if (analysis.state === "unconfigured") return "None configured"
  if (analysis.detections.length === 0) return "None detected"
  return `${analysis.detections.length} detected`
}

/**
 * One detection, and it seeks.
 *
 * The quote sits on its own surface and the explanation does not, because they
 * carry different weight: one is what the caller said and can be checked
 * against the transcript, the other is the model's reading of it. Rendered as
 * two equal paragraphs a reader has no way to tell which is which — and telling
 * them apart is the entire reason the PRD makes evidence mandatory.
 *
 * Which is also why the row is clickable: pressing it puts the playhead on the
 * quote and brings that turn up in the transcript beside it.
 */
function DetectionRow({
  detection,
  onSeek,
}: {
  detection: Detection
  onSeek: (seconds: number) => void
}) {
  const alert = CONFIGURED_ALERTS.find((item) => item.id === detection.alertId)

  return (
    <Seekable
      /* No hover tint. The card sits still; the pointer and the focus ring
         are what say it is pressable. */
      className="flex gap-3 rounded-lg bg-card p-3"
      label={`Seek to ${formatTimeSeconds(detection.at)}`}
      onActivate={() => {
        onSeek(detection.at)
      }}
    >
      {/* Severity twice, deliberately: the rule is what a reader sorts the
          list by at a glance, the badge is what they read. */}
      <span
        aria-hidden
        className={cn(
          "w-0.5 shrink-0 rounded-sm",
          SEVERITY_RULE[detection.severity],
        )}
      />

      <div className="flex min-w-0 flex-1 flex-col gap-2">
        <div className="flex items-start justify-between gap-2">
          <span className="text-sm font-medium text-foreground">
            {alert?.name ?? detection.alertId}
          </span>
          <SeverityBadge severity={detection.severity} />
        </div>

        <blockquote className="rounded-lg bg-muted p-2">
          <p className="text-sm text-foreground" dir="auto">
            &ldquo;{detection.evidence}&rdquo;
          </p>
          <span className="text-xs text-muted-foreground tabular-nums">
            {formatTimeSeconds(detection.at)}
          </span>
        </blockquote>

        <p className="text-sm text-muted-foreground">{detection.explanation}</p>
      </div>
    </Seekable>
  )
}

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Field, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Switch } from "@/components/ui/switch"
import { Textarea } from "@/components/ui/textarea"
import {
  PRIORITY_LABELS,
  PRIORITY_ORDER,
  type AlertPriority,
  type ConfiguredAlert,
} from "@/lib/mockups/behavioral-alerts-data"

const DESCRIPTION_LIMIT = 500

/**
 * Adding or editing one alert. Four fields, which is the whole definition — the
 * PRD's target is a client defining their own alerts in under two minutes.
 *
 * No helper text under any of them. Description is the one field whose job is
 * not obvious from its label, and a placeholder showing a real alert does that
 * better than a sentence explaining it would: the format is the example.
 */
export function AlertFormDialog({
  alert,
  onOpenChange,
  onSave,
  open,
}: {
  /** The alert being edited, or null when this is a new one. */
  alert: ConfiguredAlert | null
  onOpenChange: (open: boolean) => void
  onSave: (alert: ConfiguredAlert) => void
  open: boolean
}) {
  /* Seeded once, from whichever alert is being edited. The parent remounts this
     component every time it opens it — see the `key` on the call site — so the
     draft is fresh without an effect copying props into state on every open. */
  const [name, setName] = React.useState(alert?.name ?? "")
  const [description, setDescription] = React.useState(alert?.description ?? "")
  const [priority, setPriority] = React.useState<AlertPriority>(
    alert?.priority ?? "medium",
  )
  const [enabled, setEnabled] = React.useState(alert?.enabled ?? true)

  const complete = name.trim().length > 0 && description.trim().length > 0

  return (
    <Dialog onOpenChange={onOpenChange} open={open}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>{alert ? "Edit flag" : "Add flag"}</DialogTitle>
        </DialogHeader>

        <Field>
          <FieldLabel htmlFor="alert-name">Name</FieldLabel>
          <Input
            id="alert-name"
            onChange={(event) => {
              setName(event.target.value)
            }}
            placeholder="Escalation request"
            value={name}
          />
        </Field>

        <Field>
          <FieldLabel htmlFor="alert-description">Description</FieldLabel>
          <Textarea
            id="alert-description"
            maxLength={DESCRIPTION_LIMIT}
            onChange={(event) => {
              setDescription(event.target.value)
            }}
            placeholder="The caller asks to speak to a manager, a supervisor, or a human agent."
            rows={4}
            value={description}
          />
          <span className="text-xs text-muted-foreground tabular-nums">
            {description.length} / {DESCRIPTION_LIMIT}
          </span>
        </Field>

        <Field>
          <FieldLabel htmlFor="alert-priority">Priority</FieldLabel>
          <Select
            onValueChange={(value) => {
              setPriority(value as AlertPriority)
            }}
            value={priority}
          >
            <SelectTrigger id="alert-priority">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {PRIORITY_ORDER.map((level) => (
                <SelectItem key={level} value={level}>
                  {PRIORITY_LABELS[level]}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </Field>

        <Field orientation="horizontal">
          <FieldLabel htmlFor="alert-enabled">Enabled</FieldLabel>
          <Switch
            checked={enabled}
            id="alert-enabled"
            onCheckedChange={setEnabled}
          />
        </Field>

        <DialogFooter>
          <DialogClose asChild>
            <Button variant="ghost">Cancel</Button>
          </DialogClose>
          <Button
            disabled={!complete}
            onClick={() => {
              onSave({
                id: alert?.id ?? `alert-${name.trim().toLowerCase()}`,
                name: name.trim(),
                description: description.trim(),
                priority,
                enabled,
              })
            }}
          >
            {alert ? "Save changes" : "Add flag"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import * as React from "react"
import type { PanelImperativeHandle } from "react-resizable-panels"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  ResizableHandle,
  ResizablePanel,
  ResizablePanelGroup,
} from "@/components/ui/resizable"
import { Separator } from "@/components/ui/separator"
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetTitle,
} from "@/components/ui/sheet"
import {
  CONFIGURED_ALERTS,
  OWNER,
  type CallRow,
} from "@/lib/mockups/behavioral-alerts-data"
import {
  CallCompletedIcon,
  CopyCallLinkIcon,
  CopyIdIcon,
  InboundIcon,
  LanguageIcon,
  OrganizationIcon,
  OutboundIcon,
  OwnerIcon,
  ShowPanelIcon,
  VoicemailIcon,
} from "@/components/mockups/behavioral-alerts/icons"
import { SectionRegister } from "@/components/mockups/behavioral-alerts/section-register"
import { SEVERITY_RULE } from "@/components/mockups/behavioral-alerts/severity"
import {
  TranscriptPanel,
  type Evidence,
} from "@/components/mockups/behavioral-alerts/transcript-panel"

/**
 * The call detail in the revamped drawer, with the alert analysis in it.
 *
 * This is the shape the Conversations revamp settled on and not a second draft
 * of it: the header rail, the resizable split, the recording and the panel of
 * reorderable sections all behave the way they do on `/conversations-revamp`.
 * What the PRD adds arrives as two more sections in that panel — User
 * experience and Alerts — rather than as a fifth tab, because the revamp has no
 * tabs left to add one to.
 *
 * The two halves talk to each other, which is the point of putting the analysis
 * here rather than on a tab of its own. Every detection is drawn on the
 * waveform at the second its quote was said, pressing one seeks the recording
 * and scrolls the transcript to that turn, and the turn names the alert it
 * triggered. A detection nobody can find in the call is a detection nobody can
 * check, and checkability is the whole reason the PRD makes evidence mandatory.
 */
export function CallDrawer({
  call,
  onConfigureAlerts,
  onOpenChange,
  open,
}: {
  call: CallRow | null
  onConfigureAlerts: () => void
  onOpenChange: (open: boolean) => void
  open: boolean
}) {
  if (!call) return null

  return (
    <Sheet onOpenChange={onOpenChange} open={open}>
      {/* Keyed by the call: the playhead, the split and the search box all
          belong to the call being read, not to the drawer. */}
      <DrawerBody
        call={call}
        key={call.id}
        onConfigureAlerts={onConfigureAlerts}
      />
    </Sheet>
  )
}

function DrawerBody({
  call,
  onConfigureAlerts,
}: {
  call: CallRow
  onConfigureAlerts: () => void
}) {
  const [at, setAt] = React.useState(0)
  const content = React.useRef<HTMLDivElement>(null)

  /**
   * Dragging the handle past a half's minimum snaps that half shut rather than
   * stopping at the minimum. Reading a transcript and reading the panel are
   * different jobs, and the reader doing one of them wants the whole drawer for
   * it — a 35% strip of the other is not a compromise, it is two cramped halves.
   *
   * The collapsed half keeps its handle, so it drags back. `hidden` exists so
   * there is also a button for it: a 4px separator against the edge of the
   * sheet is a target you have to know about to find.
   */
  const transcript = React.useRef<PanelImperativeHandle>(null)
  const panel = React.useRef<PanelImperativeHandle>(null)
  const [hidden, setHidden] = React.useState<"none" | "panel" | "transcript">(
    "none",
  )

  const detections = call.analysis.detections

  /** One waveform marker per detection, toned by its severity. */
  const markers = detections.map((detection) => ({
    id: detection.id,
    label: alertName(detection.alertId),
    at: detection.at,
    tone: SEVERITY_RULE[detection.severity],
  }))

  /** What a quoted turn says about itself, keyed by the second it was said. */
  const evidence = new Map<number, Evidence>(
    detections.map((detection) => [
      detection.at,
      { name: alertName(detection.alertId), severity: detection.severity },
    ]),
  )

  return (
    <SheetContent
      className="flex w-full flex-col sm:max-w-6xl! lg:overflow-hidden"
      /**
       * Without this, touching the resize handle shuts the drawer.
       *
       * The dialog does not decide "was that click outside me?" by asking the
       * DOM. It sets a flag from its own React pointer-down handler, and treats
       * a missing flag as outside. The resize separator listens for pointer-down
       * natively and stops the event there — so React's handler never runs, the
       * flag is never set, and a press on the handle is read as a press on the
       * page behind the drawer.
       *
       * So answer the question the dialog was actually asking: if the press
       * really landed inside this panel, it was not outside. A genuine click on
       * the overlay still closes, and so do Escape and the close button.
       */
      onPointerDownOutside={(event) => {
        const target = event.detail.originalEvent.target
        if (target instanceof Node && content.current?.contains(target)) {
          event.preventDefault()
        }
      }}
      ref={content}
      /* The close button sat on top of the Call ID button in the header.
         Escape and a click on the overlay both still shut the drawer. */
      showCloseButton={false}
    >
      <SheetTitle className="sr-only">Call details</SheetTitle>
      <SheetDescription className="sr-only">
        {call.scenario}, {call.phoneNumber}, {call.startedAt}
      </SheetDescription>

      <div className="flex min-h-0 flex-1 flex-col">
        <CallHeader
          actions={
            hidden === "none" ? null : (
              <Button
                onClick={() => {
                  ;(hidden === "transcript"
                    ? transcript
                    : panel
                  ).current?.expand()
                }}
                size="sm"
                variant="outline"
              >
                <ShowPanelIcon />
                {hidden === "transcript" ? "Show transcript" : "Show panel"}
              </Button>
            )
          }
          call={call}
        />

        {/* Sizes are strings on purpose: react-resizable-panels reads a bare
            number as pixels and a string as a percentage.

            `minSize` is the point a half gives up rather than the point it
            stops shrinking — a collapsible panel dragged under its minimum
            collapses. Neither half caps its width, since either one has to be
            able to reach the full drawer.

            The split resets each time the drawer opens. Unlike the section
            order it is a reading choice for this call, not a standing
            preference. */}
        <ResizablePanelGroup
          className="min-h-0 flex-1 p-4"
          orientation="horizontal"
        >
          <ResizablePanel
            collapsible
            defaultSize="62%"
            id="transcript"
            minSize="35%"
            onResize={(size) => {
              setHidden((current) =>
                size.asPercentage === 0
                  ? "transcript"
                  : current === "transcript"
                    ? "none"
                    : current,
              )
            }}
            panelRef={transcript}
          >
            <TranscriptPanel
              at={at}
              call={call}
              evidence={evidence}
              markers={markers}
              onSeek={setAt}
            />
          </ResizablePanel>

          <ResizableHandle className="mx-4" withHandle />

          <ResizablePanel
            collapsible
            defaultSize="38%"
            id="panel"
            minSize="22%"
            onResize={(size) => {
              setHidden((current) =>
                size.asPercentage === 0
                  ? "panel"
                  : current === "panel"
                    ? "none"
                    : current,
              )
            }}
            panelRef={panel}
          >
            <SectionRegister
              call={call}
              onConfigureAlerts={onConfigureAlerts}
              onSeek={setAt}
            />
          </ResizablePanel>
        </ResizablePanelGroup>
      </div>
    </SheetContent>
  )
}

function alertName(alertId: string) {
  return CONFIGURED_ALERTS.find((item) => item.id === alertId)?.name ?? alertId
}

/**
 * The metadata that gets read, in one line under the title. The two IDs sit
 * beside it as buttons, the way the revamp has them.
 */
function CallHeader({
  /** Appended after Link and Call ID. Omitted, the header is unchanged. */
  actions,
  call,
}: {
  actions?: React.ReactNode
  call: CallRow
}) {
  return (
    <div className="flex shrink-0 flex-col gap-2 border-b p-4">
      <div className="flex items-start justify-between gap-4">
        <div className="flex min-w-0 flex-col gap-1">
          <div className="flex items-center gap-2">
            <h2 className="truncate text-xl font-semibold text-foreground">
              {call.scenario}
            </h2>
            {call.status === "completed" ? (
              <Badge className="bg-success-tint text-success-tint-foreground">
                <CallCompletedIcon />
                completed
              </Badge>
            ) : (
              <Badge className="bg-muted text-muted-foreground">
                <VoicemailIcon />
                voicemail
              </Badge>
            )}
          </div>

          <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted-foreground">
            <span className="flex items-center gap-1 font-medium text-foreground">
              {call.direction === "inbound" ? (
                <InboundIcon className="size-3.5" />
              ) : (
                <OutboundIcon className="size-3.5" />
              )}
              {call.phoneNumber}
            </span>
            <Separator className="h-3" orientation="vertical" />
            <span className="flex items-center gap-1">
              <OrganizationIcon className="size-3.5" />
              {OWNER.organization}
            </span>
            <span className="flex items-center gap-1">
              <OwnerIcon className="size-3.5" />
              {OWNER.email}
            </span>
            <span className="flex items-center gap-1">
              <LanguageIcon className="size-3.5" />
              {call.language}
            </span>
            <Separator className="h-3" orientation="vertical" />
            <span>{call.startedAt}</span>
            <span className="tabular-nums">
              {Math.floor(call.duration / 60)}m {call.duration % 60}s
            </span>
          </div>
        </div>

        <div className="flex shrink-0 items-center gap-1">
          <Button size="sm" variant="ghost">
            <CopyCallLinkIcon />
            Link
          </Button>
          <Button size="sm" variant="ghost">
            <CopyIdIcon />
            Call ID
          </Button>
          {actions}
        </div>
      </div>
    </div>
  )
}

"use client"

import {
  ArrowDown01Icon,
  ArrowDownLeft01Icon,
  ArrowUp01Icon,
  ArrowUpRight01Icon,
  BotIcon,
  Building02Icon,
  Cancel01Icon,
  CancelCircleIcon,
  CheckmarkCircle02Icon,
  Clock01Icon,
  Copy01Icon,
  DashboardSpeed01Icon,
  Database01Icon,
  Delete02Icon,
  Download01Icon,
  DragDropVerticalIcon,
  Flag02Icon,
  Edit02Icon,
  GlobeIcon,
  InformationCircleIcon,
  Link02Icon,
  MoreHorizontalIcon,
  PauseIcon,
  PlayIcon,
  PlusSignIcon,
  PreferenceVerticalIcon,
  QuoteDownIcon,
  Search01Icon,
  Settings01Icon,
  SidebarRight01Icon,
  StarIcon,
  UserIcon,
  UserStar01Icon,
  VoiceIcon,
  Wrench01Icon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/shared/icon"

/**
 * Icons for the behavioural alerts screens, named for the job they do here.
 *
 * The severity of a detection is carried by its badge and its marker, not by an
 * icon per row — three near-identical warning glyphs down a list say less than
 * three words do.
 */

/** The alerts section, and the empty state when nothing has been configured. */
export const FlagsIcon = icon(Flag02Icon, "FlagsIcon")

/** Marks the evidence block as a quotation lifted out of the transcript. */
export const EvidenceIcon = icon(QuoteDownIcon, "EvidenceIcon")

/** One rung of the satisfaction rating. Filled with `fill-current`. */
export const RatingStarIcon = icon(StarIcon, "RatingStarIcon")

/** The caller got what they rang for. */
export const PurposeMetIcon = icon(CheckmarkCircle02Icon, "PurposeMetIcon")

/** The caller did not get what they rang for. */
export const PurposeMissedIcon = icon(Cancel01Icon, "PurposeMissedIcon")

export const RationaleIcon = icon(InformationCircleIcon, "RationaleIcon")

/** Opens the scenario the alerts are configured on. */
export const ScenarioSettingsIcon = icon(Settings01Icon, "ScenarioSettingsIcon")

export const AddAlertIcon = icon(PlusSignIcon, "AddAlertIcon")
export const EditAlertIcon = icon(Edit02Icon, "EditAlertIcon")
export const DeleteAlertIcon = icon(Delete02Icon, "DeleteAlertIcon")
export const RowMenuIcon = icon(MoreHorizontalIcon, "RowMenuIcon")

/* ------------------------------------------- the drawer the alerts live in */

/* The header rail: which way the call went, and who it belongs to. */
export const InboundIcon = icon(ArrowDownLeft01Icon, "InboundIcon")
export const OutboundIcon = icon(ArrowUpRight01Icon, "OutboundIcon")
export const OrganizationIcon = icon(Building02Icon, "OrganizationIcon")
export const OwnerIcon = icon(UserIcon, "OwnerIcon")
export const LanguageIcon = icon(GlobeIcon, "LanguageIcon")
export const CopyCallLinkIcon = icon(Link02Icon, "CopyCallLinkIcon")
export const CopyIdIcon = icon(Copy01Icon, "CopyIdIcon")

/* The call's own status, and the verdict on its success criteria. */
export const CallCompletedIcon = icon(
  CheckmarkCircle02Icon,
  "CallCompletedIcon",
)
export const VoicemailIcon = icon(VoiceIcon, "VoicemailIcon")
export const CriterionMetIcon = icon(CheckmarkCircle02Icon, "CriterionMetIcon")
export const CriterionMissedIcon = icon(CancelCircleIcon, "CriterionMissedIcon")
export const GeneratedAtIcon = icon(Clock01Icon, "GeneratedAtIcon")

/* The recording player. */
export const PlayRecordingIcon = icon(PlayIcon, "PlayRecordingIcon")
export const PauseRecordingIcon = icon(PauseIcon, "PauseRecordingIcon")
export const PlaybackSpeedIcon = icon(DashboardSpeed01Icon, "PlaybackSpeedIcon")
export const DownloadRecordingIcon = icon(
  Download01Icon,
  "DownloadRecordingIcon",
)

/* Whoever is speaking, in the transcript. */
export const AgentIcon = icon(BotIcon, "AgentIcon")
export const CallerIcon = icon(UserIcon, "CallerIcon")

/* Searching the transcript. */
export const SearchIcon = icon(Search01Icon, "SearchIcon")
export const PrevMatchIcon = icon(ArrowUp01Icon, "PrevMatchIcon")
export const NextMatchIcon = icon(ArrowDown01Icon, "NextMatchIcon")
export const ClearSearchIcon = icon(Cancel01Icon, "ClearSearchIcon")

/* The panel of sections beside it: what each one is, and how it is rearranged. */
export const ExperienceIcon = icon(UserStar01Icon, "ExperienceIcon")
export const CollectedIcon = icon(Database01Icon, "CollectedIcon")
export const TechnicalIcon = icon(Wrench01Icon, "TechnicalIcon")
export const SectionToggleIcon = icon(ArrowDown01Icon, "SectionToggleIcon")
export const CustomizeIcon = icon(PreferenceVerticalIcon, "CustomizeIcon")
export const DragHandleIcon = icon(DragDropVerticalIcon, "DragHandleIcon")

/* Bringing back a half of the split that was dragged shut. */
export const ShowPanelIcon = icon(SidebarRight01Icon, "ShowPanelIcon")

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"
import {
  DownloadRecordingIcon,
  PauseRecordingIcon,
  PlaybackSpeedIcon,
  PlayRecordingIcon,
} from "@/components/mockups/behavioral-alerts/icons"

/**
 * The recording player from the revamped call drawer.
 *
 * The waveform and its transport row live in one tinted box: play and the time
 * readout at the start, and the things you do to the recording rather than to
 * the playhead — speed, download — collected at the end.
 *
 * The real one is wavesurfer.js against the signed URL, so the bars here are
 * static and the colours are the nearest tokens.
 */

const PLAYBACK_RATES = [
  { label: "0.5x speed", value: "0.5" },
  { label: "0.75x speed", value: "0.75" },
  { label: "1x speed (normal)", value: "1" },
  { label: "1.25x speed", value: "1.25" },
  { label: "1.5x speed", value: "1.5" },
  { label: "2x speed", value: "2" },
]

const BARS = 144

/**
 * Deterministic pseudo-noise. The server and the client have to draw the same
 * bars, so this stands in for `Math.random`, which would not.
 */
function noise(index: number) {
  const value = Math.sin(index * 12.9898) * 43758.5453
  return value - Math.floor(value)
}

/**
 * Normalised bar heights, 0–1, the way wavesurfer draws them from the audio.
 *
 * Shaped rather than flat: a slow envelope gives the loud stretches where
 * somebody is talking and the quiet ones between them, and the noise on top
 * keeps neighbouring bars from marching.
 */
const WAVE = Array.from({ length: BARS }, (_, index) => {
  const position = index / BARS
  const envelope = 0.3 + 0.7 * Math.abs(Math.sin(position * Math.PI * 3.7))
  const detail = 0.35 + 0.65 * noise(index)

  return Math.min(1, Math.max(0.1, envelope * detail))
})

export function formatTimeSeconds(seconds: number) {
  return `${Math.floor(seconds / 60)}:${(seconds % 60)
    .toString()
    .padStart(2, "0")}`
}

export type RecordingMarker = {
  id: string
  label: string
  /** Seconds into the recording. */
  at: number
  /** The token class the marker is drawn in. */
  tone: string
}

export function RecordingPlayer({
  at = 0,
  duration,
  markers,
  onSeek,
}: {
  /** Where the playhead sits, in seconds. */
  at?: number
  duration: number
  /**
   * Drawn on the waveform at the second each one happened. Here that is one
   * per detection: the moment the quote the analyst lifted was said.
   */
  markers?: RecordingMarker[]
  onSeek: (seconds: number) => void
}) {
  const [playing, setPlaying] = React.useState(false)
  const [rate, setRate] = React.useState("1")

  const played = Math.round((at / duration) * BARS)

  return (
    /* Wave and controls in one tinted box rather than a box with a loose row of
       buttons under it. They are one instrument: the transport moves the
       playhead the wave draws, and the time readout is the same number the
       playhead is at. */
    <div className="flex shrink-0 flex-col overflow-hidden rounded-lg bg-muted">
      <div className="p-4">
        <div
          aria-label="Seek in the recording"
          className="relative flex h-10 cursor-pointer items-center gap-px focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
          onClick={(event) => {
            const box = event.currentTarget.getBoundingClientRect()
            const ratio = (event.clientX - box.left) / box.width
            onSeek(Math.round(Math.min(Math.max(ratio, 0), 1) * duration))
          }}
          role="button"
          tabIndex={0}
        >
          {/* The bars flex to fill rather than sitting at a fixed width: the
              track spans the panel, and the panel is resizable. If they did
              not, the wave would end partway across while clicking to seek and
              the markers below both still measured the full width — so the
              picture and the positions would disagree. */}
          {Array.from({ length: BARS }, (_, index) => (
            <span
              className={cn(
                "min-w-px flex-1 rounded-sm transition-colors duration-150 ease-out-cubic motion-reduce:transition-none",
                index <= played && at > 0 ? "bg-primary-light" : "bg-border",
              )}
              key={index}
              style={{ height: `${(WAVE[index] * 100).toFixed(1)}%` }}
            />
          ))}

          {/* A detection is anchored to a moment in the call, so the waveform
              is the only place it can honestly be drawn. */}
          {markers?.map((marker) => (
            <Tooltip key={marker.id}>
              <TooltipTrigger
                aria-label={`${marker.label} at ${formatTimeSeconds(marker.at)}`}
                className={cn(
                  "absolute inset-y-0 w-0.5 -translate-x-1/2 rounded-sm",
                  marker.tone,
                )}
                onClick={(event) => {
                  event.stopPropagation()
                  onSeek(marker.at)
                }}
                style={{
                  insetInlineStart: `${(marker.at / duration) * 100}%`,
                }}
              />
              <TooltipContent>
                {marker.label} · {formatTimeSeconds(marker.at)}
              </TooltipContent>
            </Tooltip>
          ))}
        </div>
      </div>

      {/* One transport row, and every control on it the same height. Play is
          the only filled one, because it is the only thing you press without
          looking. */}
      <div className="flex items-center gap-2 border-t border-border px-3 py-2">
        <Button
          aria-label={playing ? "Pause" : "Play"}
          onClick={() => {
            setPlaying(!playing)
          }}
          size="icon-sm"
        >
          {playing ? <PauseRecordingIcon /> : <PlayRecordingIcon />}
        </Button>

        <span className="font-mono text-sm text-muted-foreground tabular-nums">
          {formatTimeSeconds(at)} / {formatTimeSeconds(duration)}
        </span>

        <div className="ms-auto flex items-center gap-1">
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button size="sm" variant="ghost">
                <PlaybackSpeedIcon />
                {rate}x
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="start">
              <DropdownMenuRadioGroup onValueChange={setRate} value={rate}>
                {PLAYBACK_RATES.map((option) => (
                  <DropdownMenuRadioItem
                    key={option.value}
                    value={option.value}
                  >
                    {option.label}
                  </DropdownMenuRadioItem>
                ))}
              </DropdownMenuRadioGroup>
            </DropdownMenuContent>
          </DropdownMenu>

          <Button size="sm" variant="ghost">
            <DownloadRecordingIcon />
            Download
          </Button>
        </div>
      </div>
    </div>
  )
}

