import { cn } from "@/lib/utils"

/**
 * A clickable surface that is not a Button, ported from the revamped drawer.
 *
 * The transcript bubbles and the detection rows carry their own shape, and a
 * Button would fight its own padding and radius. Keyboard behaviour is the part
 * that has to be kept by hand.
 */
export function Seekable({
  children,
  className,
  label,
  onActivate,
}: {
  children: React.ReactNode
  className?: string
  label: string
  onActivate: () => void
}) {
  return (
    <div
      aria-label={label}
      className={cn(
        "cursor-pointer focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
        className,
      )}
      onClick={onActivate}
      onKeyDown={(event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault()
          onActivate()
        }
      }}
      role="button"
      tabIndex={0}
    >
      {children}
    </div>
  )
}

"use client"

import { Badge } from "@/components/ui/badge"
import { cn } from "@/lib/utils"
import {
  PRIORITY_LABELS,
  SENTIMENT_LABELS,
  SEVERITY_LABELS,
  type AlertPriority,
  type AlertSeverity,
  type Sentiment,
} from "@/lib/mockups/behavioral-alerts-data"

/**
 * The three colour-carrying chips on these screens, kept together so the two
 * three-step scales cannot drift apart in tone.
 *
 * Mild is deliberately NOT green. Severity says how bad this call was, and the
 * bottom of that scale is "worth knowing", not "good" — a green Mild next to a
 * red Severe reads as a pass/fail axis, which is the exact reading the whole
 * feature exists to stop the platform giving.
 */

const SEVERITY_TONE: Record<AlertSeverity, string> = {
  mild: "bg-muted text-muted-foreground",
  moderate: "bg-warning-tint text-warning-tint-foreground",
  severe: "bg-destructive-tint text-destructive-tint-foreground",
}

/** The rule down the start edge of a detection card, at full strength. */
export const SEVERITY_RULE: Record<AlertSeverity, string> = {
  mild: "bg-border",
  moderate: "bg-warning",
  severe: "bg-destructive",
}

/**
 * The dot on a call row in the list, at the same three strengths.
 *
 * Tinted by the worst thing detected rather than always red: a call whose only
 * detection is a Positive sentiment moment is marked, and a red dot on it would
 * say the opposite of what it found. Mild takes `muted-foreground` rather than
 * the rule's `border`, which at 8px on a white row is not there at all.
 */
export const SEVERITY_DOT: Record<AlertSeverity, string> = {
  mild: "bg-muted-foreground",
  moderate: "bg-warning",
  severe: "bg-destructive",
}

export function SeverityBadge({ severity }: { severity: AlertSeverity }) {
  return (
    <Badge className={SEVERITY_TONE[severity]}>
      {SEVERITY_LABELS[severity]}
    </Badge>
  )
}

/**
 * Priority is triage, not alarm — it orders the admin's own list and says
 * nothing about any particular call. So it is one outline chip with a dot that
 * changes, rather than three differently-coloured chips that would read as
 * three severities the moment they sit near a detection.
 *
 * One hue at three opacities rather than three chart slots. High, medium and
 * low are a rank, and DES-174 turned --chart-* into six unrelated hues — on
 * that palette these three dots would be blue, amber and violet, which is a
 * set, not a scale. Ordinal data gets one colour and less of it.
 */
const PRIORITY_DOT: Record<AlertPriority, string> = {
  high: "bg-primary",
  low: "bg-primary/30",
  medium: "bg-primary/60",
}

export function PriorityBadge({ priority }: { priority: AlertPriority }) {
  return (
    <Badge variant="outline">
      <span
        aria-hidden
        className={cn("size-1.5 rounded-4xl", PRIORITY_DOT[priority])}
      />
      {PRIORITY_LABELS[priority]}
    </Badge>
  )
}

const SENTIMENT_TONE: Record<Sentiment, string> = {
  angry: "bg-destructive-tint text-destructive-tint-foreground",
  frustrated: "bg-warning-tint text-warning-tint-foreground",
  neutral: "bg-muted text-muted-foreground",
  positive: "bg-success-tint text-success-tint-foreground",
}

export function SentimentBadge({ sentiment }: { sentiment: Sentiment }) {
  return (
    <Badge className={SENTIMENT_TONE[sentiment]}>
      {SENTIMENT_LABELS[sentiment]}
    </Badge>
  )
}

"use client"

import * as React from "react"

import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "@/components/ui/input-group"
import { cn } from "@/lib/utils"
import type {
  AlertSeverity,
  CallRow,
} from "@/lib/mockups/behavioral-alerts-data"
import {
  AgentIcon,
  CallerIcon,
  ClearSearchIcon,
  NextMatchIcon,
  PrevMatchIcon,
  SearchIcon,
} from "@/components/mockups/behavioral-alerts/icons"
import {
  formatTimeSeconds,
  RecordingPlayer,
  type RecordingMarker,
} from "@/components/mockups/behavioral-alerts/recording-player"
import { Seekable } from "@/components/mockups/behavioral-alerts/seekable"
import { SeverityBadge } from "@/components/mockups/behavioral-alerts/severity"

/**
 * The left half of the revamped drawer: the recording, a search box, and the
 * turns.
 *
 * The one thing here that is not carried over unchanged is the evidence mark on
 * a turn. A detection promises a direct quote, and that promise is only
 * checkable if the reader can land on the line it came from — so the quoted
 * turn names the alert it triggered, and the detection in the panel seeks here.
 */

/** What a turn says about itself when a detection quoted it. */
export type Evidence = { name: string; severity: AlertSeverity }

export function TranscriptPanel({
  at,
  call,
  evidence,
  markers,
  onSeek,
}: {
  at: number
  call: CallRow
  /** Keyed by the turn's second, which is what a detection points at. */
  evidence: Map<number, Evidence>
  markers: RecordingMarker[]
  onSeek: (seconds: number) => void
}) {
  const [query, setQuery] = React.useState("")
  const [active, setActive] = React.useState(0)
  const turnRefs = React.useRef<Record<number, HTMLDivElement | null>>({})

  /** Every match in the transcript, in the order the turns are rendered. */
  const matches = React.useMemo(() => {
    const ranges = new Map<number, [number, number][]>()
    const offsets = new Map<number, number>()
    let total = 0

    call.transcript.forEach((line, index) => {
      const found = findMatches(line.text, query)
      ranges.set(index, found)
      offsets.set(index, total)
      total += found.length
    })

    return { offsets, ranges, total }
  }, [call.transcript, query])

  const search: Search = { ...matches, activeIndex: active }

  /** A shorter result list must not leave the cursor pointing past the end. */
  function runSearch(next: string) {
    setQuery(next)
    setActive(0)
  }

  function step(by: number) {
    if (!matches.total) return
    setActive((current) => (current + by + matches.total) % matches.total)
  }

  /**
   * Walking to a match moves the playhead too — the point of finding a line is
   * usually to hear it.
   */
  React.useEffect(() => {
    if (!matches.total) return

    const index = call.transcript.findIndex((_, turn) => {
      const offset = matches.offsets.get(turn) ?? 0
      const count = matches.ranges.get(turn)?.length ?? 0
      return active >= offset && active < offset + count
    })
    if (index === -1) return

    scrollTo(turnRefs.current[index])
    onSeek(call.transcript[index].at)
  }, [active, call.transcript, matches, onSeek])

  /**
   * Seeking from anywhere — the waveform, a marker, a detection in the panel —
   * brings the turn that was being spoken into view. Without it, clicking a
   * detection's quote moves a playhead the reader cannot see.
   */
  React.useEffect(() => {
    const index = activeTurn(call, at)
    if (index !== -1) scrollTo(turnRefs.current[index])
  }, [at, call])

  return (
    <div className="flex h-full min-h-0 flex-col gap-3 overflow-x-clip">
      <RecordingPlayer
        at={at}
        duration={call.duration}
        markers={markers}
        onSeek={onSeek}
      />

      <InputGroup className="shrink-0">
        <InputGroupAddon>
          <SearchIcon />
        </InputGroupAddon>
        <InputGroupInput
          onChange={(event) => {
            runSearch(event.target.value)
          }}
          onKeyDown={(event) => {
            if (event.key === "Escape") runSearch("")
            if (event.key === "Enter") {
              event.preventDefault()
              step(event.shiftKey ? -1 : 1)
            }
          }}
          placeholder="Search transcript"
          value={query}
        />
        {query ? (
          <InputGroupAddon align="inline-end">
            <span
              className={cn(
                "tabular-nums",
                search.total ? "text-muted-foreground" : "text-destructive",
              )}
            >
              {search.total ? `${active + 1} of ${search.total}` : "0"}
            </span>
            <InputGroupButton
              aria-label="Previous match"
              disabled={!search.total}
              onClick={() => {
                step(-1)
              }}
              size="icon-xs"
            >
              <PrevMatchIcon />
            </InputGroupButton>
            <InputGroupButton
              aria-label="Next match"
              disabled={!search.total}
              onClick={() => {
                step(1)
              }}
              size="icon-xs"
            >
              <NextMatchIcon />
            </InputGroupButton>
            <InputGroupButton
              aria-label="Clear search"
              onClick={() => {
                runSearch("")
              }}
              size="icon-xs"
            >
              <ClearSearchIcon />
            </InputGroupButton>
          </InputGroupAddon>
        ) : null}
      </InputGroup>

      {call.transcript.length === 0 ? (
        <p className="py-12 text-center text-sm text-muted-foreground">
          No transcript for this call.
        </p>
      ) : (
        <div className="scrollbar-hide flex min-h-0 flex-1 flex-col gap-3 overflow-y-auto p-1">
          {call.transcript.map((line, index) => {
            const next = call.transcript[index + 1]

            return (
              <TurnRow
                evidence={evidence.get(line.at)}
                isPlaying={at >= line.at && (!next || at < next.at)}
                key={index}
                line={line}
                onSeek={onSeek}
                ref={(node) => {
                  turnRefs.current[index] = node
                }}
                search={search}
                turnIndex={index}
              />
            )
          })}
        </div>
      )}
    </div>
  )
}

/** Which turn was being spoken at a given second. */
function activeTurn(call: CallRow, at: number) {
  return call.transcript.findIndex((line, index) => {
    const next = call.transcript[index + 1]
    return at >= line.at && (!next || at < next.at)
  })
}

function scrollTo(node: HTMLDivElement | null) {
  node?.scrollIntoView({
    behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches
      ? "auto"
      : "smooth",
    block: "center",
  })
}

function findMatches(text: string, query: string): [number, number][] {
  const needle = query.trim().toLowerCase()
  if (!needle) return []

  const haystack = text.toLowerCase()
  const found: [number, number][] = []
  let from = 0

  for (;;) {
    const index = haystack.indexOf(needle, from)
    if (index === -1) break
    found.push([index, index + needle.length])
    from = index + needle.length
  }

  return found
}

type Search = {
  /** Which hit the counter is pointing at, across every turn. */
  activeIndex: number
  offsets: Map<number, number>
  ranges: Map<number, [number, number][]>
  total: number
}

function TurnRow({
  evidence,
  isPlaying,
  line,
  onSeek,
  ref,
  search,
  turnIndex,
}: {
  evidence?: Evidence
  isPlaying: boolean
  line: CallRow["transcript"][number]
  onSeek: (seconds: number) => void
  ref: (node: HTMLDivElement | null) => void
  search: Search
  turnIndex: number
}) {
  const isCaller = line.speaker === "caller"

  return (
    <div
      className={cn("flex scroll-mt-1 gap-3", isCaller && "flex-row-reverse")}
      ref={ref}
    >
      <span
        className={cn(
          "flex size-8 shrink-0 items-center justify-center rounded-4xl",
          isCaller ? "bg-muted text-foreground" : "bg-primary/10 text-primary",
        )}
      >
        {isCaller ? (
          <CallerIcon className="size-4" />
        ) : (
          <AgentIcon className="size-4" />
        )}
      </span>

      <Seekable
        className={cn(
          "flex max-w-[80%] flex-col items-start gap-1 rounded-lg px-4 py-2.5 text-start transition-colors duration-150 ease-out-cubic motion-reduce:transition-none",
          isCaller
            ? "bg-primary text-primary-foreground hover:bg-primary-dark"
            : "bg-muted text-foreground hover:bg-accent",
          isPlaying && "ring-2 ring-primary",
        )}
        label={`Seek to ${formatTimeSeconds(line.at)}`}
        onActivate={() => {
          onSeek(line.at)
        }}
      >
        <span className="flex w-full items-center gap-2 text-xs opacity-70">
          {/* Same treatment as the Conversations drawer: the speaker is a label
              on the turn, not a word in it, and the caps keep it from reading
              as the first word of what was said. */}
          <span className="font-semibold tracking-wide uppercase">
            {isCaller ? "Customer" : "Agent"}
          </span>
          <span className="ms-auto tabular-nums">
            {formatTimeSeconds(line.at)}
          </span>
        </span>

        <span className="text-sm" dir="auto">
          <Highlighted search={search} text={line.text} turnIndex={turnIndex} />
        </span>

        {/* The line a detection quoted says which alert it triggered. The
            badge is the same one the detection carries in the panel, so the
            two ends of the claim are recognisably the same claim. */}
        {evidence ? (
          <span className="flex items-center gap-2 pt-1">
            <SeverityBadge severity={evidence.severity} />
            <span className="text-xs opacity-70">{evidence.name}</span>
          </span>
        ) : null}
      </Seekable>
    </div>
  )
}

/** Marks every hit, and the one the counter is currently pointing at. */
function Highlighted({
  search,
  text,
  turnIndex,
}: {
  search: Search
  text: string
  turnIndex: number
}) {
  const ranges = search.ranges.get(turnIndex)
  if (!ranges?.length) return text

  const offset = search.offsets.get(turnIndex) ?? 0
  const parts: React.ReactNode[] = []
  let cursor = 0

  ranges.forEach(([start, end], index) => {
    if (start > cursor) parts.push(text.slice(cursor, start))
    parts.push(
      <mark
        className={cn(
          "rounded-sm bg-warning/25 text-foreground",
          offset + index === search.activeIndex && "bg-primary/30",
        )}
        key={start}
      >
        {text.slice(start, end)}
      </mark>,
    )
    cursor = end
  })

  if (cursor < text.length) parts.push(text.slice(cursor))

  return parts
}

"use client"

import type { ReactNode } from "react"

import { DataTableHeaderRow } from "@/components/shared/data-table"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import {
  COLUMN_HELP,
  COLUMN_LABELS,
  type CallRow,
  type ColumnId,
  type ColumnSetting,
} from "@/lib/mockups/conversations-revamp-list-data"
import {
  AgentOutcomeBadge,
  DirectionChip,
  OutcomeBadge,
  ScenarioChip,
  StatusBadge,
} from "@/components/mockups/conversations-revamp/list/status-badges"
import { StatusHelp } from "@/components/mockups/conversations-revamp/list/status-help"
import { TimeIcon } from "@/components/mockups/conversations-revamp/list/icons"

/**
 * The table, driven by whatever the Fields dropdown says.
 *
 * Header and body both walk the same `columns` array, so a column cannot end up
 * in one and not the other, and reordering is a single list to move.
 */
export function CallTable({
  calls,
  columns,
  onCallClick,
  rowMarker,
}: {
  /** Owned by the page, because cancelling a scheduled call changes one. */
  calls: CallRow[]
  columns: ColumnSetting[]
  onCallClick: (call: CallRow) => void
  /**
   * A mark on the row's time icon, for a mockup whose calls carry a finding the
   * columns do not — the behavioural flags, in practice.
   *
   * It rides the icon rather than taking a column of its own: a column would
   * cost width on every row to say nothing on most of them, and this is the
   * absence of a value rather than a value. Rows with nothing to report return
   * null; the mockups that pass nothing get the table exactly as it was.
   */
  rowMarker?: (call: CallRow) => ReactNode
}) {
  const shown = columns.filter((column) => column.visible)

  return (
    <Table>
      <TableHeader>
        <DataTableHeaderRow>
          {shown.map((column) => (
            <TableHead
              className="font-semibold text-foreground"
              key={column.id}
            >
              {/* The help icon only appears on columns that carry a
                  COLUMN_HELP entry, so it marks the one header worth reading
                  rather than decorating every one of them. */}
              {COLUMN_HELP[column.id] ? (
                <span className="inline-flex items-center gap-1">
                  {COLUMN_LABELS[column.id]}
                  {/* A legend rather than a tooltip — see StatusHelp for why
                      five definitions are the wrong thing to put in one. */}
                  <StatusHelp />
                </span>
              ) : (
                COLUMN_LABELS[column.id]
              )}
            </TableHead>
          ))}
        </DataTableHeaderRow>
      </TableHeader>

      <TableBody>
        {calls.map((call) => (
          <TableRow
            className="cursor-pointer transition-colors duration-150 ease-out-cubic hover:bg-muted/50 motion-reduce:transition-none"
            key={call.id}
            onClick={() => {
              onCallClick(call)
            }}
          >
            {shown.map((column) => (
              <TableCell key={column.id}>
                <Cell
                  call={call}
                  column={column.id}
                  marker={column.id === "time" ? rowMarker?.(call) : null}
                />
              </TableCell>
            ))}
          </TableRow>
        ))}
      </TableBody>
    </Table>
  )
}

/**
 * One placeholder for every cell that has no value, so a blank never has to be
 * interpreted. Direction used to render nothing at all on a chat row while
 * Phone Number rendered "-" — two ways of saying "no value here" in one row.
 *
 * The two verdict columns keep their own wording, because there the absence
 * *is* a reading: Unavailable is one of the things each of them reports.
 */
function NoValue() {
  return (
    <span aria-label="Not applicable" className="text-muted-foreground">
      —
    </span>
  )
}

function Cell({
  call,
  column,
  marker,
}: {
  call: CallRow
  column: ColumnId
  /** Rendered against the time icon; positioned by whoever passes it. */
  marker?: ReactNode
}) {
  switch (column) {
    case "direction":
      return call.direction ? (
        <DirectionChip direction={call.direction} />
      ) : (
        <NoValue />
      )

    case "duration":
      return call.duration === "-" ? (
        <NoValue />
      ) : (
        <span className="text-sm font-medium text-foreground">
          {call.duration}
        </span>
      )

    /* The chip is the verdict; the tooltip is why it reads that way, and only
       a call that produced one has a why to give. */
    case "outcome":
      return call.outcomeReason ? (
        <Tooltip>
          <TooltipTrigger asChild>
            <span>
              <OutcomeBadge status={call.outcome} />
            </span>
          </TooltipTrigger>
          <TooltipContent>
            <p className="max-w-xs">{call.outcomeReason}</p>
          </TooltipContent>
        </Tooltip>
      ) : (
        <OutcomeBadge status={call.outcome} />
      )

    case "agentOutcome":
      return <AgentOutcomeBadge status={call.agentOutcome} />

    case "phoneNumber":
      return call.phoneNumber ? (
        <span className="text-sm font-medium text-foreground">
          {call.phoneNumber}
        </span>
      ) : (
        <NoValue />
      )

    case "scenario":
      return <ScenarioChip scenario={call.scenario} />

    case "status":
      return (
        <StatusBadge
          scheduleOrigin={call.scheduleOrigin}
          status={call.status}
        />
      )

    case "time":
      return (
        <div className="flex items-center text-muted-foreground">
          <span className="relative me-2 flex">
            <TimeIcon className="size-3.5" />
            {marker}
          </span>
          <span className="text-sm">{call.createdAt}</span>
        </div>
      )
  }
}

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { cn } from "@/lib/utils"
import {
  COLUMN_LABELS,
  DEFAULT_COLUMNS,
  type ColumnId,
  type ColumnSetting,
} from "@/lib/mockups/conversations-revamp-list-data"
import {
  DragHandleIcon,
  FieldsIcon,
} from "@/components/mockups/conversations-revamp/list/icons"

/**
 * Which columns the table shows, and in what order.
 *
 * This is what replaced the Default View / Detailed View picker. Two saved
 * views could not answer the questions people actually bring to this table, and
 * a third view per question is how a picker turns into a menu nobody reads —
 * so the columns are chosen directly instead.
 *
 * Drag to reorder, tick to show. The same interaction as the call drawer's
 * panel, because it is the same decision: what belongs on screen, and where.
 */
export function FieldsDropdown({
  columns,
  onChange,
}: {
  columns: ColumnSetting[]
  onChange: (columns: ColumnSetting[]) => void
}) {
  const [dragging, setDragging] = React.useState<ColumnId | null>(null)
  /** Where the dragged row would land — the index the drop line sits before. */
  const [dropAt, setDropAt] = React.useState<null | number>(null)

  const shown = columns.filter((column) => column.visible).length

  function move(from: number, to: number) {
    if (to < 0 || to >= columns.length || from === to) return
    const next = [...columns]
    const [moved] = next.splice(from, 1)
    next.splice(to, 0, moved)
    onChange(next)
  }

  /** Drop uses an insertion point, which shifts once the row is lifted out. */
  function moveTo(from: number, insertAt: number) {
    const next = [...columns]
    const [moved] = next.splice(from, 1)
    next.splice(insertAt > from ? insertAt - 1 : insertAt, 0, moved)
    onChange(next)
  }

  function toggle(id: ColumnId) {
    onChange(
      columns.map((column) =>
        column.id === id ? { ...column, visible: !column.visible } : column,
      ),
    )
  }

  function endDrag() {
    setDragging(null)
    setDropAt(null)
  }

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button
          aria-label="Choose fields"
          className="bg-card font-normal"
          variant="outline"
        >
          <FieldsIcon className="text-muted-foreground" />
          Fields
          {shown < columns.length ? (
            <span className="text-muted-foreground">
              {shown}/{columns.length}
            </span>
          ) : null}
        </Button>
      </PopoverTrigger>

      <PopoverContent align="end" className="flex w-64 flex-col gap-3">
        <div className="flex flex-col gap-0.5">
          <span className="text-sm font-medium">Fields</span>
          <span className="text-sm text-muted-foreground">
            Drag to reorder. Untick to take a column off the table.
          </span>
        </div>

        <div className="flex flex-col">
          {columns.map((column, index) => (
            <div
              className={cn(
                "relative flex items-center gap-2 rounded-lg py-1 pe-2 transition-opacity duration-150 ease-out-cubic motion-reduce:transition-none",
                dragging === column.id && "opacity-40",
              )}
              draggable
              key={column.id}
              onDragEnd={endDrag}
              onDragOver={(event) => {
                event.preventDefault()
                // Past the midpoint means it lands after this row, not before.
                const box = event.currentTarget.getBoundingClientRect()
                const below = event.clientY > box.top + box.height / 2
                setDropAt(below ? index + 1 : index)
              }}
              onDragStart={() => {
                setDragging(column.id)
              }}
              onDrop={() => {
                const from = columns.findIndex((entry) => entry.id === dragging)
                if (from !== -1 && dropAt !== null) moveTo(from, dropAt)
                endDrag()
              }}
            >
              {/* Absolutely positioned so showing it does not shove the rows
                  around while you are still dragging. */}
              {dropAt === index ? <DropLine className="-top-px" /> : null}
              {dropAt === columns.length && index === columns.length - 1 ? (
                <DropLine className="-bottom-px" />
              ) : null}

              {/* A button, not just the glyph: dragging has no keyboard
                  equivalent, so the handle takes arrow keys itself. */}
              <Button
                aria-label={`Reorder ${COLUMN_LABELS[column.id]}`}
                className="shrink-0 cursor-grab text-muted-foreground"
                onKeyDown={(event) => {
                  if (event.key === "ArrowUp") {
                    event.preventDefault()
                    move(index, index - 1)
                  }
                  if (event.key === "ArrowDown") {
                    event.preventDefault()
                    move(index, index + 1)
                  }
                }}
                size="icon-xs"
                variant="ghost"
              >
                <DragHandleIcon />
              </Button>

              <span className="flex-1 truncate text-sm">
                {COLUMN_LABELS[column.id]}
              </span>

              <Checkbox
                aria-label={`Show ${COLUMN_LABELS[column.id]}`}
                checked={column.visible}
                onCheckedChange={() => {
                  toggle(column.id)
                }}
              />
            </div>
          ))}
        </div>

        <Button
          className="self-end"
          onClick={() => {
            onChange(DEFAULT_COLUMNS)
          }}
          size="sm"
          variant="ghost"
        >
          Reset
        </Button>
      </PopoverContent>
    </Popover>
  )
}

/** Where the dragged row will land. */
function DropLine({ className }: { className: string }) {
  return (
    <span
      className={cn(
        "pointer-events-none absolute inset-x-0 h-0.5 rounded-sm bg-primary",
        className,
      )}
    />
  )
}

